{"code": "
import bisect
from collections import defaultdict

n = int(input())
strengths = list(map(int, input().split()))
t = int(input())
queries = [tuple(map(int, input().split())) for _ in range(t)]

# Preprocess: for each value, store sorted list of positions
pos = defaultdict(list)
for idx, val in enumerate(strengths):
    pos[val].append(idx + 1)  # 1-indexed

results = []

for l, r in queries:
    # Get all values in the range [l, r]
    values = set()
    for i in range(l, r + 1):
        values.add(strengths[i - 1])

    # Count occurrences of each value in the range
    count = {}
    for val in values:
        lst = pos[val]
        left = bisect.bisect_left(lst, l)
        right_idx = bisect.bisect_right(lst, r)
        count[val] = right_idx - left

    # For each position i in [l, r], calculate its points
    points = {}
    for i in range(l, r + 1):
        val = strengths[i - 1]
        points[i] = 0
        # Add points from multiples of val
        for m in range(val, max(values) + 1, val):
            if m in count:
                points[i] += count[m]

    # Count how many ants have exactly (r-l) points
    freed = 0
    for i in range(l, r + 1):
        if points[i] == r - l:
            freed += 1

    results.append(n - (r - l + 1) + freed)  # Eaten ants = total ants - freed ants

for res in results:
    print(res)
