def mex(grundy_numbers):
    """Calculate mex (minimum excludant) of a set of integers."""
    mex = 0
    while mex in grundy_numbers:
        mex += 1
    return mex

# Calculate Grundy numbers up to m
max_length = m
grundy = [0] * (max_length + 1)

for length in range(k, max_length + 1):
    # Calculate all possible outcomes for splitting this log
    outcomes = set()

    # Try all possible splits
    for t in range(2, length + 1):
        if length % t == 0:
            part_length = length // t
            if part_length >= k:
                # Calculate Grundy number for t parts of length part_length
                if t % 2 == 0:
                    # Even number of parts, XOR is 0
                    outcome = 0
                else:
                    # Odd number of parts, XOR is grundy[part_length]
                    outcome = grundy[part_length]
                outcomes.add(outcome)

    # Calculate Grundy number for this length
    grundy[length] = mex(outcomes)

# Calculate overall Grundy number for n logs
if n % 2 == 1:
    overall_grundy = grundy[m]
else:
    overall_grundy = 0

# Determine winner
if overall_grundy != 0:
    print("Timur")
else:
    print("Marsel")
"}

