import math

def distance(p1, p2):
    """Calculate Euclidean distance between two points"""
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def solve():
    N = int(input())
    cities = []
    for _ in range(N):
        X, Y, F = map(int, input().split())
        cities.append((X, Y, F))

    # dp[i] = maximum happiness ending at city i (0-indexed)
    dp = [0] * N
    dp[0] = cities[0][2]  # Start at city 1 (0-indexed)

    for i in range(1, N):
        max_happiness = -float('inf')
        for j in range(i):
            # Happiness from going from city j to city i
            happiness = dp[j] + cities[i][2] - distance(cities[j], cities[i])
            if happiness > max_happiness:
                max_happiness = happiness
        dp[i] = max_happiness

    print(f"{dp[N-1]:.6f}")

solve()
