    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    Q = int(next(it))

    # Dictionary: prefix -> suffix -> count
    prefix_suffix_counts = {}

    for _ in range(N):
        word = next(it)

        # Add to prefix dictionary
        for i in range(1, len(word) + 1):
            prefix = word[:i]
            if prefix not in prefix_suffix_counts:
                prefix_suffix_counts[prefix] = {}

            # Add to suffix dictionary for this prefix
            suffix = word[i:]
            if suffix not in prefix_suffix_counts[prefix]:
                prefix_suffix_counts[prefix][suffix] = 0
            prefix_suffix_counts[prefix][suffix] += 1

    # Process queries
    out_lines = []
    for _ in range(Q):
        p = next(it)
        s = next(it)

        if p not in prefix_suffix_counts:
            out_lines.append('0')
