import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        arr = list(map(int, data[idx:idx+n]))
        idx += n

        evens = 0
        odds = 0
        for num in arr:
            if num % 2 == 0:
                evens += 1
            else:
                odds += 1

        if abs(evens - odds) > 1:
            results.append("-1")
            continue

        # Count mismatches for both patterns
        # Pattern 1: even at even indices (1-indexed), odd at odd indices
        # Pattern 2: odd at even indices, even at odd indices

        # Pattern 1: even at even indices (0-indexed: even indices are 0, 2, 4...)
        # Pattern 2: odd at even indices (0-indexed: even indices are 0, 2, 4...)

        # Count mismatches for pattern 1: even at even indices, odd at odd indices
        mismatch1 = 0
        for i in range(n):
            if i % 2 == 0 and arr[i] % 2 != 0:
                mismatch1 += 1
            elif i % 2 == 1 and arr[i] % 2 == 0:
                mismatch1 += 1

        # Count mismatches for pattern 2: odd at even indices, even at odd indices
        mismatch2 = 0
        for i in range(n):
            if i % 2 == 0 and arr[i] % 2 == 0:
                mismatch2 += 1
            elif i % 2 == 1 and arr[i] % 2 != 0:
                mismatch2 += 1

        results.append(str(min(mismatch1, mismatch2)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
