def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

n = int(input())
a = list(map(int, input().split()))

# Compute GCD of all numbers
all_gcd = a[0]
for num in a[1:]:
    all_gcd = gcd(all_gcd, num)

# Divide each number by the overall GCD
b = [num // all_gcd for num in a]

# Count prime factors for each number
from collections import defaultdict

# Function to factorize a number
def factorize(x):
    factors = defaultdict(int)
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] += 1
            x //= i
        i += 1
    if x > 1:
        factors[x] += 1
    return factors

# Get all prime factors across all numbers
all_factors = defaultdict(int)
for num in b:
    factors = factorize(num)
    for p, cnt in factors.items():
        all_factors[p] += 1

# Build result
result = 1
for p, cnt in all_factors.items():
    # If prime appears in at least n-1 numbers, it's in the GCD
    if cnt >= n - 1:
        # Find minimum exponent across all numbers that contain p
        min_exp = float('inf')
        for num in b:
            if num % p == 0:
                min_exp = min(min_exp, num // (num // p))  # num // (num // p) gives exponent
        result *= p ** min_exp

print(result)
