def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    if not data:
        return

    N = int(data[0])
    L = int(data[1])
    A = list(map(int, data[2:2+N]))

    # Precompute p_max for all i from 1 to L
    p_max = [0] * (L + 1)  # 1-indexed

    for i in range(1, L + 1):
        # Find prime factorization of i
        prime_factors = {}
        temp = i

        # Check primes up to sqrt(temp)
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                prime_factors[p] = count

        # If remaining temp > 1, it's a prime factor
        if temp > 1:
            prime_factors[temp] = 1

        if not prime_factors:
            p_max[i] = 0
        else:
            # Find prime with max exponent (and smallest prime if tie)
            max_exp = max(prime_factors.values())
            candidates = [p for p, exp in prime_factors.items() if exp == max_exp]
            p_max[i] = min(candidates)

    # Process operations
    for i in range(1, L + 1):
        if not A:
            break

        if i == 1 or (p_max[i] % i) % 2 == 1:
            # Beneficial: double the smallest element
            A[A.index(min(A))] *= 2
        else:
            # Harmful: divide the largest element
            A[A.index(max(A))] //= 2

        # Remove elements that became 0
        A = [x for x in A if x != 0]

    # Output
    print(len(A))
    if A:
        print(' '.join(map(str, sorted(A))))

if __name__ == "__main__":
    solve()
"}

