import sys
import heapq
from collections import defaultdict, deque

def dijkstra(n, adj, start):
    """Find shortest distances from start to all other nodes"""
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue

        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return dist

def bfs_shortest_paths(n, adj, start, end, dist):
    """Find all nodes that are on any shortest path from start to end"""
    visited = [False] * (n + 1)
    queue = deque([start])
    visited[start] = True

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if dist[v] == dist[u] + w and not visited[v]:
                visited[v] = True
                queue.append(v)

    return visited

def find_shortest_paths(n, adj, start, end, dist):
    """Find all shortest paths from start to end"""
    # First, find all nodes on any shortest path
    visited = bfs_shortest_paths(n, adj, start, end, dist)

    # Now find all paths from start to end that only go through shortest path nodes
    paths = []

    # Use BFS to find all paths
    queue = deque([(start, [start])])

    while queue:
        u, path = queue.popleft()

        if u == end:
            paths.append(path)
            continue

        for v, w in adj[u]:
            if dist[v] == dist[u] + w and visited[v] and v not in path:
                queue.append((v, path + [v]))

    return paths

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    adj = defaultdict(list)
    edges = []

    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        z = int(next(it))
        adj[x].append((y, z))
        adj[y].append((x, z))
        edges.append((x, y, z))

    # Dijkstra to find shortest distances
    dist = dijkstra(n, adj, 1)

    # Find all shortest paths from 1 to n
    paths = find_shortest_paths(n, adj, 1, n, dist)

    if not paths:
        return

    # Find the path with minimum affected roads
    min_affected = float('inf')
    best_path = None

    for path in paths:
        affected = 0

        # Traverse the path and count affected roads
        for i in range(len(path) - 1):
            u = path[i]
            v = path[i + 1]

            # Find the road between u and v
            for (x, y, z) in edges:
                if (x == u and y == v) or (x == v and y == u):
                    # This road is on the path
                    if z == 0:
                        affected += 1  # Need to repair
                    break

        # Count roads that need to be blown up (not on path and working)
        for (x, y, z) in edges:
            if z == 1:
                # Check if this road is on any shortest path
                on_path = False
                for i in range(len(path) - 1):
                    if (x == path[i] and y == path[i + 1]) or (x == path[i + 1] and y == path[i]):
                        on_path = True
                        break

                if not on_path:
                    affected += 1  # Need to blow up

        if affected < min_affected:
            min_affected = affected
            best_path = path

    # Output the result
    print(min_affected)

    # Output affected roads
    # First, output roads that need to be blown up (not on path and working)
    for (x, y, z) in edges:
        if z == 1:
            on_path = False
            for i in range(len(best_path) - 1):
                if (x == best_path[i] and y == best_path[i + 1]) or (x == best_path[i + 1] and y == best_path[i]):
                    on_path = True
                    break

            if not on_path:
                print(x, y, 0)

    # Then, output roads that need to be repaired (on path and not working)
    for i in range(len(best_path) - 1):
        u = best_path[i]
        v = best_path[i + 1]

        for (x, y, z) in edges:
            if (x == u and y == v) or (x == v and y == u):
                if z == 0:
                    print(x, y, 1)
                break

if __name__ == '__main__':
    solve()
