import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        s = data[idx]
        idx += 1

        found = False

        # Try all possible substrings
        for i in range(n):
            a_count = 0
            b_count = 0

            for j in range(i, n):
                if s[j] == 'a':
                    a_count += 1
                else:
                    b_count += 1

                # Check if we have a balanced substring
                if a_count == b_count:
                    results.append(f"{i+1} {j+1}")
                    found = True
                    break

        if not found:
            results.append("-1 -1")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

